const themeStorageKey="portfolio-theme";document.querySelector(".theme-toggle")?.addEventListener("click",()=>{const e=document.documentElement.dataset.theme==="dark"?"light":"dark";document.documentElement.dataset.theme=e,localStorage.setItem(themeStorageKey,e)});const showcaseCarousel=document.querySelector(".showcase-carousel");function moveShowcaseCarousel(e){if(!showcaseCarousel)return;const t=showcaseCarousel.querySelector(".showcase-slide"),n=t?t.getBoundingClientRect().width+20:showcaseCarousel.clientWidth;showcaseCarousel.scrollBy({left:e*n,behavior:"smooth"})}document.querySelectorAll("[data-carousel-direction]").forEach(e=>{e.addEventListener("click",()=>{moveShowcaseCarousel(e.dataset.carouselDirection==="next"?1:-1)})}),showcaseCarousel?.addEventListener("keydown",e=>{(e.key==="ArrowRight"||e.key==="ArrowLeft")&&(e.preventDefault(),moveShowcaseCarousel(e.key==="ArrowRight"?1:-1))})